root<-'/mnt/BioDisk/wangmingyuan/tongbian_formal_20261012'
out<-file.path(root,'05_human_RNA/sample_QC_v1');dir.create(out,recursive=TRUE,showWarnings=FALSE)
suppressPackageStartupMessages(library(DESeq2))
dds<-readRDS(file.path(root,'05_human_RNA/R_DESeq2_bridge_v1/R_DESeq2_fit.rds'))
vst<-as.matrix(read.delim(file.path(root,'05_human_RNA/R_DESeq2_bridge_v1/R_DESeq2_blind_VST_tested.tsv'),row.names=1,check.names=FALSE))
meta<-as.data.frame(colData(dds));stopifnot(identical(meta$sample,colnames(vst)))
design<-model.matrix(~condition,meta);sf<-sizeFactors(dds)
raw<-sapply(seq_len(nrow(meta)),function(i){
 d<-read.delim(gzfile(file.path(root,'03_inputs/GSE245885_pilot/raw',meta$supplement_file[i])),check.names=FALSE)
 z<-d[[paste0(meta$sample[i],'.count')]]
 c(total_counts=sum(z),detected_genes=sum(z>0),genes_ge10=sum(z>=10))
})
colnames(raw)<-meta$sample
cook<-assays(dds)[['cooks']];cutoff<-qf(.99,ncol(design),nrow(meta)-ncol(design))
corr<-cor(vst,method='pearson');spear<-cor(vst,method='spearman')
write.table(corr,file.path(out,'sample_correlation_Pearson_all_VST.tsv'),sep='\t',quote=FALSE,col.names=NA)
write.table(spear,file.path(out,'sample_correlation_Spearman_all_VST.tsv'),sep='\t',quote=FALSE,col.names=NA)
distances<-as.matrix(dist(t(vst)));write.table(distances,file.path(out,'sample_Euclidean_distance_all_VST.tsv'),sep='\t',quote=FALSE,col.names=NA)
rv<-apply(vst,1,var);sel<-head(order(rv,decreasing=TRUE),500)
pc<-prcomp(t(vst[sel,,drop=FALSE]),center=TRUE,scale.=FALSE)
pcall<-prcomp(t(vst),center=TRUE,scale.=FALSE)
pct<-100*pc$sdev^2/sum(pc$sdev^2);pctall<-100*pcall$sdev^2/sum(pcall$sdev^2)
pcs<-data.frame(sample=meta$sample,condition=meta$condition,pc$x,check.names=FALSE)
write.table(pcs,file.path(out,'PCA_top500_variable_VST_scores.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
write.table(data.frame(sample=meta$sample,condition=meta$condition,pcall$x,check.names=FALSE),file.path(out,'PCA_all_VST_scores.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
write.table(data.frame(PC=seq_along(pct),top500_percent_variance=pct,all_genes_percent_variance=pctall),file.path(out,'PCA_variance_explained.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
within<-sapply(seq_len(nrow(meta)),function(i)mean(corr[i,which(meta$condition==meta$condition[i]&seq_len(nrow(meta))!=i)]))
between<-sapply(seq_len(nrow(meta)),function(i)mean(corr[i,meta$condition!=meta$condition[i]]))
center_distance<-sapply(seq_len(nrow(meta)),function(i){g<-meta$condition==meta$condition[i];sqrt(sum((vst[,i]-rowMeans(vst[,g,drop=FALSE]))^2))})
qc<-data.frame(sample=meta$sample,condition=meta$condition,raw_library_count=raw['total_counts',],detected_genes=raw['detected_genes',],genes_ge10=raw['genes_ge10',],prefiltered_library_count=colSums(counts(dds)),size_factor=sf,median_VST=apply(vst,2,median),mean_Pearson_within_group=within,mean_Pearson_other_group=between,distance_to_own_group_VST_centroid=center_distance,genes_Cooks_above_cutoff=colSums(cook>cutoff,na.rm=TRUE),maximum_Cooks=apply(cook,2,max,na.rm=TRUE),automatic_exclusion=FALSE)
write.table(qc,file.path(out,'sample_QC_all_samples.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
write.table(data.frame(sample=meta$sample,design,check.names=FALSE),file.path(out,'design_matrix.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
write.table(data.frame(ensembl_id=rownames(dds),max_Cooks=apply(cook,1,max,na.rm=TRUE),above_cutoff=apply(cook,1,max,na.rm=TRUE)>cutoff),file.path(out,'gene_Cooks_audit.tsv'),sep='\t',quote=FALSE,row.names=FALSE)
same<-outer(as.character(meta$condition),as.character(meta$condition),'==');upper<-upper.tri(corr)
summary<-list(samples=10,groups=as.list(table(meta$condition)),raw_library_count_range=range(qc$raw_library_count),raw_library_ratio=max(qc$raw_library_count)/min(qc$raw_library_count),size_factor_range=range(sf),size_factor_ratio=max(sf)/min(sf),PCA_top500_PC1_PC2_percent=pct[1:2],PCA_all_PC1_PC2_percent=pctall[1:2],within_group_Pearson_range=range(corr[same&upper]),between_group_Pearson_range=range(corr[!same&upper]),lowest_within_group_correlation_sample=qc$sample[which.min(within)],farthest_within_group_centroid_sample=qc$sample[which.max(center_distance)],maximum_sample_Cooks_count=qc$sample[which.max(qc$genes_Cooks_above_cutoff)],Cooks_cutoff=cutoff,genes_max_Cooks_above_cutoff=sum(apply(cook,1,max,na.rm=TRUE)>cutoff),design='~condition',design_rank=qr(design)$rank,design_columns=ncol(design),residual_df=nrow(meta)-ncol(design),age_sex_segment_batch_available=FALSE,samples_removed=character(),notes='Counts are supplied gene-assigned counts, not sequencer read yield. Outlier metrics are descriptive in n=5/group, not exclusion rules. No sample removal or design change. Cancer-surgery controls are not healthy volunteers; unmeasured clinical, segment, batch and cell-composition effects remain possible.')
jsonlite::write_json(summary,file.path(out,'sample_QC_summary.json'),pretty=TRUE,auto_unbox=TRUE)
colors<-ifelse(meta$condition=='STC','#BA5B3B','#2F6F8F')
png(file.path(out,'Figure_sample_QC.png'),width=2000,height=1600,res=170,type='cairo')
par(mfrow=c(2,2),mar=c(8,5,3,1))
barplot(qc$raw_library_count/1e6,names.arg=qc$sample,las=2,col=colors,ylab='Million gene-assigned counts',main='Raw count library size (all supplied genes)')
barplot(sf,names.arg=qc$sample,las=2,col=colors,ylab='DESeq2 size factor',main='Median-ratio normalization')
plot(pc$x[,1],pc$x[,2],pch=19,col=colors,xlab=sprintf('PC1 (%.1f%%)',pct[1]),ylab=sprintf('PC2 (%.1f%%)',pct[2]),main='PCA: 500 most variable blind-VST genes',xlim=range(pc$x[,1])*1.25,ylim=range(pc$x[,2])*1.3)
text(pc$x[,1],pc$x[,2],labels=meta$sample,pos=3,cex=.65);legend('bottomleft',c('Cancer-surgery control','STC'),pch=19,col=c('#2F6F8F','#BA5B3B'),cex=.7,bty='n')
plot(pcall$x[,1],pcall$x[,2],pch=19,col=colors,xlab=sprintf('PC1 (%.1f%%)',pctall[1]),ylab=sprintf('PC2 (%.1f%%)',pctall[2]),main='PCA: all 20,479 prefiltered blind-VST genes',xlim=range(pcall$x[,1])*1.25,ylim=range(pcall$x[,2])*1.3)
text(pcall$x[,1],pcall$x[,2],labels=meta$sample,pos=3,cex=.65)
dev.off()
png(file.path(out,'Figure_sample_correlation.png'),width=1500,height=1400,res=150,type='cairo')
heatmap(corr,Rowv=NA,Colv=NA,scale='none',margins=c(10,10),col=colorRampPalette(c('white','#8AB4C7','#285976'))(101),main='Pearson correlation: all prefiltered blind-VST genes')
dev.off()
png(file.path(out,'Figure_dispersion_and_P.png'),width=1600,height=800,res=150,type='cairo')
par(mfrow=c(1,2));plotDispEsts(dds)
de<-read.delim(file.path(root,'05_human_RNA/R_DESeq2_bridge_v1/R_DESeq2_all_genes.tsv'))
hist(de$pvalue[is.finite(de$pvalue)],breaks=50,col='#729CA9',border='white',main='Wald P distribution: all testable genes',xlab='Nominal P')
dev.off()
writeLines(capture.output(sessionInfo()),file.path(out,'sessionInfo.txt'))
cat(jsonlite::toJSON(summary,pretty=TRUE,auto_unbox=TRUE),'\n')
